parameters.functionCode:
// ── Build final email content v3 ──────────────────────────────────
// Upgrade 2: timezone-aware send window check (9 AM – 5 PM recipient local)
// Link tracking wraps all hrefs; open pixel + CAN-SPAM footer appended.

const step      = $input.first().json;
const trackBase = $env.N8N_WEBHOOK_BASE_URL || 'https://your-n8n.com';

// ── Timezone-aware send window ────────────────────────────────────
const COUNTRY_TZ = {
  'United States': 'America/New_York', 'US': 'America/New_York',
  'Canada': 'America/Toronto',
  'United Kingdom': 'Europe/London', 'UK': 'Europe/London',
  'Germany': 'Europe/Berlin', 'France': 'Europe/Paris',
  'Netherlands': 'Europe/Amsterdam', 'Sweden': 'Europe/Stockholm',
  'Australia': 'Australia/Sydney', 'India': 'Asia/Kolkata',
  'Singapore': 'Asia/Singapore'
};

const tz = COUNTRY_TZ[step.country || ''] || 'UTC';

const localHour = parseInt(
  new Date().toLocaleString('en-US', { timeZone: tz, hour: 'numeric', hour12: false }),
  10
);

const SEND_START = 9;    // 9 AM
const SEND_END   = 17;   // 5 PM

if (localHour < SEND_START || localHour >= SEND_END) {
  // Outside window — compute hours until next 9:30 AM in recipient tz
  const hoursUntilOpen = localHour >= SEND_END
    ? (24 - localHour) + SEND_START + 0.5   // past 5 PM → tomorrow
    : SEND_START - localHour + 0.5;           // before 9 AM → later today

  const reschedule_to = new Date(
    Date.now() + hoursUntilOpen * 60 * 60 * 1000
  ).toISOString();

  return [{
    json: {
      ...step,
      outside_send_window:  true,
      reschedule_to,
      recipient_tz:         tz,
      recipient_local_hour: localHour
    }
  }];
}

// ── Within window — build email ───────────────────────────────────
const trackId   = `${step.sequence_id}_${step.step_id}`;
const unsubUrl  = `${trackBase}/webhook/unsubscribe?l=${step.lead_id}&s=${step.sequence_id}`;
const firstName = step.first_name || step.full_name?.split(' ')[0] || 'there';

let body = (step.body_text || '')
  .replace(/\{\{\s*first_name\s*\}\}/gi, firstName)
  .replace(/\{\{\s*company\s*\}\}/gi, step.company || '');

function wrapLink(url) {
  if (url.includes('track-') || url.includes('unsubscribe')) return url;
  return `${trackBase}/webhook/track-click?t=${trackId}&l=${step.lead_id}&url=${encodeURIComponent(url)}`;
}
body = body.replace(/href="(https?:\/\/[^"]+)"/gi, (_, url) => `href="${wrapLink(url)}"`);
body = body.replace(
  /(?<!href=")(https?:\/\/[^\s<"]+)/gi,
  (url) => `<a href="${wrapLink(url)}">${url}</a>`
);

const openPixel =
  `<img src="${trackBase}/webhook/track-open?t=${trackId}&l=${step.lead_id}" ` +
  `width="1" height="1" style="display:none;" alt="" />`;

const htmlBody =
  `<div style="font-family:Arial,sans-serif;font-size:14px;line-height:1.6;color:#333;">` +
  body.replace(/\n/g, '<br>') +
  `</div><br><br>` +
  `<p style="font-size:11px;color:#aaa;border-top:1px solid #eee;padding-top:8px;">` +
  `You received this because you match the profile of people we help. ` +
  `<a href="${unsubUrl}" style="color:#aaa;">Unsubscribe</a>.` +
  `</p>` + openPixel;

return [{
  json: {
    ...step,
    outside_send_window:  false,
    recipient_tz:         tz,
    recipient_local_hour: localHour,
    first_name:           firstName,
    final_subject:        step.subject,
    final_body:           body,
    html_body:            htmlBody,
    track_id:             trackId,
    unsubscribe_url:      unsubUrl
  }
}];

// ── Extract Gmail message + thread IDs from send response ─────────
// Fix: store gmail_message_id + gmail_thread_id so WF-06 can
// match incoming replies back to the correct sequence step.
//
// Gmail send response shape:
//   { id: 'messageId', threadId: 'threadId', labelIds: [...] }

const gmailResp = $input.first().json;
const prev      = $items('Build Email Content')[0].json;

const gmailMessageId = gmailResp.id       || gmailResp.messageId || null;
const gmailThreadId  = gmailResp.threadId || null;

if (!gmailMessageId) {
  // Log missing ID as warning — don't throw, email was sent successfully
  console.warn(`WF-05: gmail_message_id missing for step ${prev.step_id}`);
}

return [{
  json: {
    ...prev,
    gmail_message_id: gmailMessageId,
    gmail_thread_id:  gmailThreadId
  }
}];

// ── Sequence step scheduler ───────────────────────────────────────
// Tier-aware cadence. Steps: 1→follow_up→value_add→break_up→end

const step = $input.first().json;
const tier = step.tier || 'B';

const cadence = {
  A: [3, 4, 5],
  B: [4, 5, 7],
  C: [5, 7, 10]
};

const delays      = cadence[tier] || cadence.B;
const currentStep = step.step_number;
const maxSteps    = 4;

if (currentStep >= maxSteps) {
  return [{ json: { ...step, next_step: null, sequence_complete: true } }];
}

const delayDays   = delays[currentStep - 1] || 5;
const nextStepNum = currentStep + 1;
const scheduledAt = new Date(Date.now() + delayDays * 24 * 60 * 60 * 1000).toISOString();

const stepTypes = { 2: 'follow_up', 3: 'value_add', 4: 'break_up' };

return [{
  json: {
    ...step,
    next_step_number:  nextStepNum,
    next_step_type:    stepTypes[nextStepNum] || 'follow_up',
    next_scheduled_at: scheduledAt,
    delay_days:        delayDays,
    sequence_complete: false
  }
}];

