={{ `Write step ${$json.next_step_number} (${$json.next_step_type}) for this sequence.

Lead: ${$json.first_name} at ${$json.company}
Tier: ${$json.tier}
Previous subject: ${$json.final_subject}
Strategy: ${$json.strategy_used || 'value_led'}

Step guidance:
- follow_up: briefly ref previous email, one new insight, under 100 words
- value_add: relevant resource or insight, no hard sell
- break_up: short, acknowledge they're busy, leave door open

Return JSON:
{
  "subject_a": "variant A",
  "subject_b": "variant B",
  "body": "plain text body",
  "preview_text": "max 90 chars",
  "confidence": 0.0-1.0
}` }}

parameters.functionCode:
const raw = $input.first().json?.choices?.[0]?.message?.content
         || $input.first().json?.message?.content || '';

let parsed = {};
try {
  const start = raw.indexOf('{');
  const end   = raw.lastIndexOf('}');
  if (start === -1 || end === -1) throw new Error('no JSON found');
  parsed = JSON.parse(raw.slice(start, end + 1));
} catch(e) {
  parsed = {
    subject_a:    `Following up — ${$json.company}`,
    subject_b:    `Quick question for ${$json.first_name}`,
    body:         `Hi ${$json.first_name},\n\nJust following up on my last email. Happy to connect when the timing works.\n\nBest,\nAlex`,
    preview_text: 'Following up on my last email',
    confidence:   0.5
  };
}

const useA    = Math.random() < 0.5;
const subject = useA ? (parsed.subject_a || parsed.subject_b) : (parsed.subject_b || parsed.subject_a);

return [{
  json: {
    ...$input.first().json,
    next_subject:          subject,
    next_subject_a:        parsed.subject_a,
    next_subject_b:        parsed.subject_b,
    next_subject_variant:  useA ? 'A' : 'B',
    next_body:             parsed.body,
    next_preview_text:     parsed.preview_text,
    next_confidence:       parseFloat(parsed.confidence) || 0.5
  }
}];

const err  = $input.first().error || {};
const step = $items('Build Email Content')[0]?.json || {};

return [{
  json: {
    step_id:       step.step_id,
    lead_id:       step.lead_id,
    sequence_id:   step.sequence_id,
    step_number:   step.step_number,
    error_message: err.message || 'unknown send error',
    execution_id:  $execution.id
  }
}];
